import React, {useState} from 'react';
import PropTypes from 'prop-types';
import {Icon} from "@iconify/react";
import useTranslation from "../hooks/useTranslation.jsx";
import {primaryColor} from "../utils/colors.jsx";
import ProBadge from "./ProBadge.jsx";
import {humanizeFieldType, upgradeUrl} from "./upgrade.jsx";
// generated by the Lite extraction: the field type names of ACPT PRO (names only)
import proFieldTypes from "./data/proFieldTypes.json";

/**
 * The field types available in ACPT PRO, shown greyed out at the bottom of the
 * field picker. Not draggable: clicking one opens the upgrade page.
 */
const LockedFieldTypes = ({search}) => {

    const [collapsed, setCollapsed] = useState(false);

    const types = proFieldTypes
        .map((type) => ({type, label: humanizeFieldType(type)}))
        .filter(({label}) => !search || label.toLowerCase().includes(search.toLowerCase()));

    if (types.length === 0) {
        return null;
    }

    return (
        <div className="flex-column s-12 acpt-lite-locked-field-types">
            <div
                className="flex-between cursor-pointer mb-12"
                role="button"
                tabIndex={0}
                aria-expanded={!collapsed}
                onClick={() => setCollapsed(!collapsed)}
                onKeyDown={e => {
                    if(e.key === 'Enter' || e.key === ' '){
                        e.preventDefault();
                        setCollapsed(!collapsed);
                    }
                }}
            >
                <h4 className="i-flex-center s-8">
                    {useTranslation("MORE FIELD TYPES")}
                    <ProBadge />
                </h4>
                <Icon icon="bx:expand-alt" width={18} color={primaryColor()} />
            </div>
            {!collapsed && (
                <React.Fragment>
                    <p className="acpt-lite-hint">
                        {useTranslation("Repeaters, relations, media, maps and many more field types are available in ACPT PRO.")}
                    </p>
                    <div className="grid grid-2 s-12">
                        {types.map(({type, label}) => (
                            <a
                                key={type}
                                href={upgradeUrl("field-types", type)}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="acpt-badge acpt-badge-disabled acpt-lite-locked-badge m-0"
                                title={useTranslation("Available in ACPT PRO")}
                            >
                                <span className="flex-between">
                                    <span className="text-ellipsis">{label}</span>
                                    <Icon icon="bx:lock-alt" width={16} />
                                </span>
                            </a>
                        ))}
                    </div>
                </React.Fragment>
            )}
        </div>
    );
};

LockedFieldTypes.propTypes = {
    search: PropTypes.string,
};

export default LockedFieldTypes;
